-- Access QueryDef: Запрос21
-- Type: 0

SELECT q.CnNum, q.CnInvNum, q.CnInvDate, q.AccountMain, q.cnpdTpOrd, q.cnpdNumNull, q.cnpdDateNull, q.cnpdKey, q.pdpCstAgPnKey, d.pdpCstAgPn AS pdpCstAgPnKeyBd, IIf([i].[pdpCstAgPnKey]=[pdpCstAgPnKeyBd],True,False) AS pdpCstAgPnKeyEqual, i.NumSequential, i.StatusOfDICtext, i.satstusOfOUKVtext, i.summ, i.cost, i.SumTax, i.costVAT, i.SPPelement, i.docOfAccountNum, d.docOfAccountNum AS docOfAccountNumBd, d.pdpKey, i.AccountDate, i.positingDate, i.accountingDoc, d.accountingDoc AS accountingDocBd, IIf([i].[accountingDoc]=[accountingDocBd],True,False) AS accountingDocEqual, i.agent, i.TextOfAgent, i.prjctDefinition, i.prjctDefinitionSort, i.prjctHierarchyLevel, i.ParentSppElementNum, i.object, d.object AS objectBd, IIf([i].[object]=[objectBd],True,False) AS objectEqual, i.cstDSW, i.raNum, i.raDate, i.CorrectionNum, i.CorrectionDate, i.accountingDocName, i.purchasingGroup, i.purchasingGroupName, i.textOfCreditor, i.supplierTIN, i.supplierKPP, q.NumSequentialCount, q.pdpCstAgPnStr, q.docOfAccountNumNull, q.accountingDocNull, q.objectNull
FROM (cn_PrDocImp_CnInvExCsosExPdExPnNt AS q LEFT JOIN cn_PrDocImp AS i ON (q.CnNum = i.cnpdCnNumNull) AND (q.CnInvNum = i.cnpdCnInvNumNull) AND (q.AccountMain = i.AccountMain) AND (q.cnpdTpOrdKey = i.cnpdTpOrdKey) AND (q.cnpdNumNull = i.cnpdNumNull) AND (q.pdpCstAgPnKey = i.pdpCstAgPnKey) AND (q.docOfAccountNumNull = i.docOfAccountNumNull) AND (q.accountingDocNull = i.accountingDocNull) AND (q.objectNull = i.objectNull)) LEFT JOIN ags_cn_PrDocP AS d ON (q.docOfAccountNumNull = d.docOfAccountNumNull) AND (q.cnpdKey = d.pdpPrDoc);
